function sumSubarrayMins(arr) {
  const MOD = 1000000007;
  const n = arr.length;
  const stack = [];
  let total = 0;

  for (let i = 0; i <= n; i++) {
    const current = i === n ? 0 : arr[i];
    while (stack.length > 0 && arr[stack[stack.length - 1]] >= current) {
      const mid = stack.pop();
      const left = stack.length > 0 ? stack[stack.length - 1] : -1;
      const count = (mid - left) * (i - mid);
      total = (total + arr[mid] * count) % MOD;
    }
    stack.push(i);
  }
  return total;
}

