function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 9);
    const top = rand() < 0.5 ? 4 : 30000;
    return [Array.from({ length: n }, () => pick(1, top))];
  }
  const n = 2000;
  const shape = pick(0, 3);
  if (shape === 0) return [Array.from({ length: n }, () => pick(1, 30000))];
  if (shape === 1) return [Array.from({ length: n }, () => 30000)];
  if (shape === 2) return [Array.from({ length: n }, (_, i) => 30000 - i * 15)];
  return [Array.from({ length: n }, (_, i) => 1 + i * 15)];
}
